import json,re
d=json.load(open('../jb_batch2.json',encoding='utf-8'))
items={x['ref']:x for x in d}
E={}
def ok(ref,e): E[ref]={"verdict":"ok","explanation":e}
def fix(ref,e,stem=None,options=None):
    x=items[ref]
    s=stem if stem is not None else x['stem']
    o=dict(options if options is not None else x['options'])
    s=s.replace(r'\textbf{List-I}','List-I').replace(r'\textbf{List-II}','List-II')
    s=re.sub(r'\n\s*\n+','\n',s).strip()
    for k in o:
        v=o[k]
        if '\\quad' in v:
            pairs=re.findall(r'\(([PQRS])\)\s*\$?\s*\\rightarrow\s*\$?\s*\((\d)\)',v)
            if len(pairs)==4:
                v='; '.join(r'$(%s) \rightarrow (%s)$'%p for p in pairs)
            else:
                v=v.replace(r'$\quad$','').strip()
        v=v.rstrip(',').rstrip('.').strip()
        o[k]=v
    E[ref]={"verdict":"fix","explanation":e,"stem":s,"options":o}
